<script setup lang="ts">
import { Eye, RefreshCw, Search, X } from '@lucide/vue';
const config = useRuntimeConfig(); const route = useRoute();
const { token } = useWorkspaceSession(); const productEditor = useState<any | null>('admin-product-editor', () => null); const selected = useState<any | null>('admin-order-selected', () => null); const notice = ref(''); const search = ref(''); const statusFilter = ref('');
const { openContextMenu, copyText } = useContextMenu();
const active = ref(String(route.query.section || 'dashboard')); watch(() => route.query.section, v => { if (typeof v === 'string') active.value = v; }, { immediate: true });
const dashboard = ref<any>(null); const products = ref<any[]>([]); const orders = ref<any[]>([]); const customers = ref<any[]>([]); const syncLogs = ref<any[]>([]); const categories = ref<any[]>([]); const busy = ref(false); const savingProduct = ref(false);
const menu = [{ id: 'dashboard', label: 'Обзор' }, { id: 'orders', label: 'Заказы' }, { id: 'products', label: 'Каталог' }, { id: 'customers', label: 'Клиенты' }, { id: 'warehouse', label: 'Склад и 1С' }, { id: 'settings', label: 'Настройки' }];
const orderStatuses = [{ id: 'NEW', label: 'Новый' }, { id: 'CONFIRMED', label: 'Подтверждён' }, { id: 'PAID', label: 'Оплачен' }, { id: 'ASSEMBLING', label: 'Сборка' }, { id: 'SHIPPED', label: 'Отправлен' }, { id: 'DELIVERED', label: 'Доставлен' }, { id: 'CANCELLED', label: 'Отменён' }, { id: 'REFUNDED', label: 'Возврат' }];
const filteredProducts = computed(() => products.value.filter(p => !search.value || `${p.nameRu} ${p.sku}`.toLowerCase().includes(search.value.toLowerCase())));
const filteredOrders = computed(() => orders.value.filter(o => (!statusFilter.value || o.status === statusFilter.value) && (!search.value || `${o.orderNumber} ${o.user?.email || ''}`.toLowerCase().includes(search.value.toLowerCase()))));
const labelStatus = (v: string) => orderStatuses.find(s => s.id === v)?.label || v;
async function load() { if (!token.value) return; busy.value = true; const headers = { Authorization: `Bearer ${token.value}` }; try { [dashboard.value, products.value, orders.value, customers.value, syncLogs.value, categories.value] = await Promise.all([$fetch('/admin/dashboard', { baseURL: config.public.apiBase, headers }), $fetch<any[]>('/admin/products', { baseURL: config.public.apiBase, headers }), $fetch<any[]>('/admin/orders', { baseURL: config.public.apiBase, headers }), $fetch<any[]>('/crm/customers', { baseURL: config.public.apiBase, headers }), $fetch<any[]>('/1c-sync/logs', { baseURL: config.public.apiBase, headers }), $fetch<any[]>('/admin/categories', { baseURL: config.public.apiBase, headers })]); } finally { busy.value = false; } }
async function archiveProduct(product: any) { await $fetch(`/admin/products/${product.id}`, { baseURL: config.public.apiBase, method: 'DELETE', headers: { Authorization: `Bearer ${token.value}` } }); product.isActive = false; notice.value = 'Товар скрыт из каталога'; setTimeout(() => notice.value = '', 2200); }
function editProduct(product: any) { productEditor.value = { id: product.id, nameRu: product.nameRu, descriptionRu: product.descriptionRu || '', price: Number(product.variants?.[0]?.price || product.basePrice || 0), stock: product.variants?.[0]?.stock || 0, isActive: product.isActive, images: (product.images || []).map((image: any) => ({ url: image.url, alt: image.alt || '' })), categoryIds: (product.categories || []).map((item: any) => item.categoryId), metaTitle: product.seo?.metaTitle || '', metaDesc: product.seo?.metaDesc || '', canonical: product.seo?.canonical || '' }; }
async function saveProduct() { if (!productEditor.value) return; savingProduct.value = true; try { const updated = await $fetch<any>(`/admin/products/${productEditor.value.id}`, { baseURL: config.public.apiBase, method: 'PATCH', headers: { Authorization: `Bearer ${token.value}` }, body: { nameRu: productEditor.value.nameRu, descriptionRu: productEditor.value.descriptionRu, price: Number(productEditor.value.price), stock: Number(productEditor.value.stock), isActive: productEditor.value.isActive, images: productEditor.value.images.filter((image: any) => image.url), categoryIds: productEditor.value.categoryIds, metaTitle: productEditor.value.metaTitle, metaDesc: productEditor.value.metaDesc, canonical: productEditor.value.canonical } }); const index = products.value.findIndex(p => p.id === updated.id); if (index >= 0) products.value[index] = updated; productEditor.value = null; notice.value = 'Товар сохранён'; setTimeout(() => notice.value = '', 2200); } finally { savingProduct.value = false; } }
function addImage() { if (productEditor.value) productEditor.value.images.push({ url: '', alt: '' }); }
async function updateOrder(order: any, status: string) { await $fetch(`/admin/orders/${order.orderNumber}/status`, { baseURL: config.public.apiBase, method: 'PATCH', headers: { Authorization: `Bearer ${token.value}` }, body: { status } }); order.status = status; notice.value = 'Статус заказа обновлён'; setTimeout(() => notice.value = '', 2200); }
function go(section: string) { navigateTo(`/admin-workspace?section=${section}`); }
function productMenu(event:MouseEvent, product:any) { openContextMenu(event, product.nameRu, [{label:'Редактировать товар',icon:'edit',action:()=>editProduct(product)},{label:'Открыть в магазине',icon:'external',action:()=>window.open(`/products/${product.slug}`,'_blank')},{label:'Копировать SKU',icon:'copy',separator:true,action:()=>copyText(product.sku,'SKU скопирован')},...(product.isActive?[{label:'Скрыть из каталога',icon:'archive' as const,danger:true,confirm:`Скрыть товар «${product.nameRu}»?`,action:()=>archiveProduct(product)}]:[])], product.sku); }
function orderMenu(event:MouseEvent, order:any) { const index=orderStatuses.findIndex(item=>item.id===order.status);const next=orderStatuses[index+1];openContextMenu(event,order.orderNumber,[{label:'Открыть карточку',icon:'open',action:()=>selected.value=order},{label:'Копировать номер',icon:'copy',action:()=>copyText(order.orderNumber,'Номер заказа скопирован')},...(next?[{label:`Статус: ${next.label}`,icon:'status' as const,separator:true,action:()=>updateOrder(order,next.id)}]:[])],order.user?.email||'Гость'); }
function customerMenu(event:MouseEvent, customer:any) { openContextMenu(event,[customer.firstName,customer.lastName].filter(Boolean).join(' ')||'Клиент',[{label:'Открыть Customer 360',icon:'open',action:()=>navigateTo(`/crm-customers?customer=${customer.id}`)},{label:'Копировать email',icon:'copy',action:()=>copyText(customer.email,'Email скопирован')}],customer.email); }
function syncMenu(event:MouseEvent, log:any) { openContextMenu(event,log.entity||'Операция 1С',[{label:'Обновить журнал',icon:'refresh',action:load},{label:'Копировать идентификатор',icon:'copy',action:()=>copyText(log.id,'Идентификатор скопирован')}],new Date(log.createdAt).toLocaleString('ru-RU')); }
function openProductFromTable(event: MouseEvent) { if (active.value !== 'products') return; const row = (event.target as HTMLElement).closest('.table .row:not(.head)'); if (!row) return; const rows = Array.from(document.querySelectorAll('.table .row:not(.head)')); const index = rows.indexOf(row); if (products.value[index]) editProduct(products.value[index]); }
onMounted(() => { load(); document.querySelector('.site-admin-console')?.addEventListener('dblclick', openProductFromTable); });
onBeforeUnmount(() => document.querySelector('.site-admin-console')?.removeEventListener('dblclick', openProductFromTable));
</script>
<template>
  <main class="site-admin-console">
    <WorkspaceLoading v-if="!dashboard" label="Загружаем управление сайтом" />
    <template v-else><header class="site-admin-header" :class="{ 'has-new-product': active === 'products' }"><div class="site-admin-heading"><p class="kicker">SARKISIAN / {{ menu.find(m => m.id === active)?.label }}</p><h1>{{ menu.find(m => m.id === active)?.label }}</h1></div><div class="header-actions"><button @click="load"><RefreshCw :size="16" :class="{spin: busy}" /> Обновить</button></div></header>
      <div class="admin-body"><section v-if="active === 'dashboard'"><div class="kpi-grid"><article><span>Заказы</span><strong>{{ dashboard.orders }}</strong><small>всего заказов</small></article><article><span>Оплачено</span><strong class="green">{{ dashboard.paidOrders }}</strong><small>успешных оплат</small></article><article><span>Клиенты</span><strong>{{ dashboard.customers }}</strong><small>зарегистрированных</small></article><article><span>Активный каталог</span><strong>{{ dashboard.products }}</strong><small>товаров опубликовано</small></article></div><div class="welcome"><div><p class="kicker">ПАНЕЛЬ УПРАВЛЕНИЯ</p><h2>Добро пожаловать в SARKISIAN</h2><p>Все ключевые операции магазина — в одном месте.</p></div><div class="quick"><button @click="go('products')">Управлять каталогом</button><button @click="go('orders')">Обработать заказы</button><button @click="go('warehouse')">Проверить склад</button></div></div></section>
      <section v-else-if="active === 'products'" class="panel"><div class="panel-head"><div><p class="kicker">ТОВАРЫ И ЦЕНЫ</p><h2>Каталог</h2><span>{{ filteredProducts.length }} позиций</span></div><label class="search"><Search :size="16" /><input v-model="search" placeholder="Поиск по названию или SKU" /></label></div><div class="table"><div class="row head"><span>Товар</span><span>Цена</span><span>Остаток</span><span>Статус</span><span></span></div><div v-for="p in filteredProducts" :key="p.id" class="row" @contextmenu.prevent="productMenu($event,p)"><div><strong>{{ p.nameRu }}</strong><small>{{ p.sku }}</small></div><span>{{ Number(p.variants?.[0]?.price || p.basePrice || 0).toLocaleString('ru-RU') }} ₽</span><span>{{ p.variants?.[0]?.stock || 0 }}</span><span :class="p.isActive ? 'green' : 'red'">{{ p.isActive ? 'Активен' : 'Скрыт' }}</span><button v-if="p.isActive" class="icon" title="Скрыть товар" @click="archiveProduct(p)"><X :size="16" /></button></div><p v-if="!filteredProducts.length" class="empty">Товары не найдены</p></div></section>
      <section v-else-if="active === 'orders'" class="panel"><div class="panel-head"><div><p class="kicker">ОПЕРАЦИИ МАГАЗИНА</p><h2>Заказы</h2><span>{{ filteredOrders.length }} заказов</span></div></div><div class="filters"><label class="search"><Search :size="16" /><input v-model="search" placeholder="Номер заказа или email" /></label><select v-model="statusFilter"><option value="">Все статусы</option><option v-for="s in orderStatuses" :key="s.id" :value="s.id">{{ s.label }}</option></select><button v-if="search || statusFilter" class="clear" @click="search='';statusFilter=''">Сбросить</button></div><div class="table order-table"><div class="row head"><span>Заказ</span><span>Клиент</span><span>Сумма</span><span>Статус</span><span>Оплата</span></div><div v-for="o in filteredOrders" :key="o.id" class="row clickable" @click="selected=o" @contextmenu.prevent="orderMenu($event,o)"><strong>{{ o.orderNumber }}</strong><span>{{ o.user?.email || 'Гость' }}</span><strong>{{ Number(o.finalAmount || 0).toLocaleString('ru-RU') }} ₽</strong><select :value="o.status" @click.stop @change="updateOrder(o, ($event.target as HTMLSelectElement).value)"><option v-for="s in orderStatuses" :key="s.id" :value="s.id">{{ s.label }}</option></select><span>{{ labelStatus(o.paymentStatus) }}</span></div><p v-if="!filteredOrders.length" class="empty">Заказов не найдено</p></div></section>
      <section v-else-if="active === 'customers'" class="panel"><div class="panel-head"><div><p class="kicker">КЛИЕНТСКАЯ БАЗА</p><h2>Клиенты</h2><span>{{ customers.length }} профилей</span></div></div><div class="table"><div class="row head"><span>Клиент</span><span>Email</span><span>Телефон</span><span>Заказы</span><span>Регистрация</span></div><div v-for="c in customers" :key="c.id" class="row" @contextmenu.prevent="customerMenu($event,c)"><div><strong>{{ [c.firstName,c.lastName].filter(Boolean).join(' ') || 'Без имени' }}</strong><small>{{ c.role }}</small></div><span>{{ c.email }}</span><span>{{ c.phone || '—' }}</span><span>{{ c._count?.orders || 0 }}</span><span>{{ new Date(c.createdAt).toLocaleDateString('ru-RU') }}</span></div></div></section>
      <section v-else-if="active === 'warehouse'" class="panel"><div class="panel-head"><div><p class="kicker">ОСТАТКИ И СИНХРОНИЗАЦИЯ</p><h2>Склад и 1С</h2><span>Контроль остатков и обмен данными</span></div></div><div class="kpi-grid compact"><article><span>Активные товары</span><strong>{{ dashboard.products }}</strong></article><article><span>Мало на складе</span><strong>{{ dashboard.lowStock }}</strong></article><article><span>Операции 1С</span><strong>{{ syncLogs.length }}</strong></article></div><div class="table"><div class="row head"><span>Операция</span><span>Статус</span><span>Дата</span><span>Записей</span><span></span></div><div v-for="log in syncLogs" :key="log.id" class="row" @contextmenu.prevent="syncMenu($event,log)"><strong>{{ log.entity || 'Товары' }}</strong><span class="green">{{ log.status }}</span><span>{{ new Date(log.createdAt).toLocaleString('ru-RU') }}</span><span>{{ log.processed ?? '—' }}</span><span></span></div></div></section>
      <section v-else class="panel settings"><div class="panel-head"><div><p class="kicker">КОНФИГУРАЦИЯ</p><h2>Настройки</h2><span>Параметры магазина и подключения</span></div></div><div class="settings-grid"><label>Название магазина<input value="SARKISIAN BRAND" /></label><label>Email поддержки<input value="info@sarkisianbrand.ru" /></label><label>Адрес API<input :value="config.public.apiBase" readonly /></label><label>Окружение<input value="Разработка" readonly /></label></div><button class="save">Сохранить настройки</button></section></div>
    </template>
    <aside v-if="selected" class="drawer-backdrop" @click.self="selected=null"><div class="drawer"><button class="close" @click="selected=null"><X :size="18" /></button><p class="kicker">ЗАКАЗ</p><h2>{{ selected.orderNumber }}</h2><dl><dt>Клиент</dt><dd>{{ selected.user?.email || 'Гость' }}</dd><dt>Сумма</dt><dd>{{ Number(selected.finalAmount || 0).toLocaleString('ru-RU') }} ₽</dd><dt>Статус</dt><dd>{{ labelStatus(selected.status) }}</dd><dt>Создан</dt><dd>{{ new Date(selected.createdAt).toLocaleString('ru-RU') }}</dd></dl></div></aside><div v-if="notice" class="toast">{{ notice }}</div>
  </main>
<aside v-if="productEditor" class="drawer-backdrop" @click.self="productEditor=null"><div class="drawer product-drawer"><button class="close" @click="productEditor=null"><X :size="18" /></button><p class="kicker">КАТАЛОГ / РЕДАКТИРОВАНИЕ</p><h2>Карточка товара</h2><label>Название<input v-model="productEditor.nameRu" /></label><label>Цена, ₽<input v-model.number="productEditor.price" type="number" min="0" /></label><label>Остаток<input v-model.number="productEditor.stock" type="number" min="0" /></label><label>Описание<textarea v-model="productEditor.descriptionRu" rows="5"></textarea></label><label class="check"><input v-model="productEditor.isActive" type="checkbox" /> Показывать в каталоге</label><button class="save" :disabled="savingProduct" @click="saveProduct">{{ savingProduct ? 'Сохраняем…' : 'Сохранить товар' }}</button></div></aside>
</template>
